/// ```
///
/// Generic form only (custom C++ syntax).
#[mlir::op("emitc.include", generic)]
pub struct IncludeOp<'a> {
    #[attr(name = "include")]
    pub include: Attribute<'a>,
    #[attr(name = "is_standard_include")]
    pub is_standard_include: bool,
}

